#!/usr/bin/env python3
"""Extract per-seminar passport content (student works) from 'clankiseminarsk enaloge' folders.
Parses Vzorec/passport docx+pdf files into structured sections → src/data/seminars.json"""
import json, re, subprocess
from pathlib import Path
from docx import Document

ROOT = Path("/home/mark/CascadeProjects/mvcp koncni (Copy)/clankiseminarsk enaloge")
OUT = Path(__file__).resolve().parent.parent / "src" / "data" / "seminars.json"

# folder number → app topic ids
FOLDER_MAP = {
    1: ["zivljenje"], 2: ["mucenje"], 3: ["izginotja"], 4: ["otroci"], 5: ["zenske"],
    6: ["invalidi"], 7: ["begunci", "migranti"], 8: ["eskp"], 9: ["eskp"],
    10: ["okolje"], 11: ["razvoj"], 12: ["genocid"], 13: ["izrazanje"],
    14: ["veroizpoved"], 15: ["samoodlocba"], 16: ["manjsine"],
}

SECTION_HEADERS = [
    "Ime pravice", "Pravna podlaga", "Definicija", "Omejitve", "Pomembnost",
    "Izzivi v implementaciji", "Primeri iz prakse", "Varnostni mehanizmi", "Nadzor",
]

def extract_passport_docx(path: Path):
    """Passport docx = table with (section | content) rows."""
    d = Document(str(path))
    sections = {}
    for t in d.tables:
        for row in t.rows:
            cells = [c.text.strip() for c in row.cells]
            if len(cells) >= 2:
                header = cells[0].strip().rstrip(":")
                content = "\n".join(c.strip() for c in cells[1:] if c.strip())
                if header and content:
                    sections[header] = content
    # also capture non-table paragraphs as intro
    intro = "\n".join(p.text.strip() for p in d.paragraphs if p.text.strip())
    return sections, intro

def extract_text(path: Path) -> str:
    try:
        if path.suffix.lower() == ".docx":
            d = Document(str(path))
            return "\n".join(p.text for p in d.paragraphs if p.text.strip())
        elif path.suffix.lower() == ".pdf":
            r = subprocess.run(["pdftotext", "-q", str(path), "-"], capture_output=True, text=True, timeout=60)
            return r.stdout
    except Exception as e:
        print(f"  WARN extract {path.name}: {e}")
    return ""

def parse_passport(text: str):
    """Split text into known sections by header lines."""
    sections = {}
    lines = text.split("\n")
    current = None
    buf = []
    for ln in lines:
        s = ln.strip().rstrip(":").strip()
        if s in SECTION_HEADERS or (s.endswith(":") and s[:-1] in SECTION_HEADERS):
            if current:
                sections[current] = "\n".join(buf).strip()
            current = s.rstrip(":").strip()
            buf = []
        elif current is not None:
            buf.append(ln)
    if current:
        sections[current] = "\n".join(buf).strip()
    return sections

def pick_student_work(files):
    """Prefer passport/vzorec docx, then pasport pdf, then pisni izdelek/seminarska pdf, then any docx."""
    pats = [
        lambda f: re.match(r"(?i)(vzorec|passport|pasport).*\.docx$", f),
        lambda f: re.match(r"(?i)pasport.*\.pdf$", f),
        lambda f: re.match(r"(?i)(pisni izdelek|seminarska).*\.pdf$", f),
        lambda f: re.match(r"(?i)vzorec.*\.pdf$", f),
        lambda f: f.lower().endswith(".docx"),
        lambda f: re.match(r"(?i)(p\d+).*pisni.*\.pdf$", f),
    ]
    for pat in pats:
        for f in files:
            if pat(f):
                return f
    return None


