results = []
for folder in sorted(ROOT.iterdir(), key=lambda p: int(re.match(r"(\d+)", p.name).group(1)) if re.match(r"(\d+)", p.name) else 99):
    m = re.match(r"(\d+)", folder.name)
    if not m or not folder.is_dir():
        continue
    num = int(m.group(1))
    files = sorted(f.name for f in folder.iterdir() if f.is_file())
    work = pick_student_work(files)
    sections, raw_len, essay = {}, 0, None
    if work:
        wp = folder / work
        if wp.suffix.lower() == ".docx":
            try:
                sections, intro = extract_passport_docx(wp)
                raw_len = sum(len(v) for v in sections.values())
                if not sections and intro:
                    essay = intro[:4000]; raw_len = len(essay)
            except Exception as e:
                print(f"  WARN docx {work}: {e}")
        else:
            text = extract_text(wp)
            raw_len = len(text)
            sections = parse_passport(text)
            if not sections and text:
                essay = text[:4000]
    # folders without passport-format work: try seminarska pdf as essay
    if not sections and not essay:
        for f in files:
            if re.match(r"(?i)(seminarska|pisni izdelek|p ?\d+ ).*\.pdf$", f) and "pogodba" not in f.lower() and "konvencija" not in f.lower() and "članek" not in f.lower():
                text = extract_text(folder / f)
                if len(text) > 500:
                    essay = text[:5000]; raw_len = len(text)
                    if not work: work = f
                    break
    topic_ids = FOLDER_MAP.get(num, [])
    sec = sections
    results.append({
        "id": topic_ids[0] if topic_ids else f"folder{num}",
        "n": num,
        "title": folder.name,
        "folderName": folder.name,
        "topicIds": topic_ids,
        "convention": sec.get("Pravna podlaga", ""),
        "definition": sec.get("Definicija", ""),
        "omejitve": sec.get("Omejitve", ""),
        "pomembnost": sec.get("Pomembnost", ""),
        "izzivi": sec.get("Izzivi v implementaciji", ""),
        "primeri": sec.get("Primeri iz prakse", ""),
        "extraSections": {k: v for k, v in sec.items()
                          if k not in ("Ime pravice", "Pravna podlaga", "Definicija", "Omejitve",
                                       "Pomembnost", "Izzivi v implementaciji", "Primeri iz prakse")},
        "studentWorkFile": work,
        "essay": essay,
        "studentWorkSummary": SUMMARIES.get(str(num), {}).get("studentWorkSummary"),
        "derivedSections": DERIVED.get(num),
        "articleSummary": SUMMARIES.get(str(num), {}).get("articleSummary"),
        "files": files,
    })
    got = ", ".join(sections.keys()) if sections else "NONE"
    print(f"  {num:2d}. {folder.name[:50]:52s} work={str(work)[:40]:42s} sections: {got}")


# merge derived sections for essay-type works
for r in results:
    dv = DERIVED.get(str(r["n"])) or DERIVED.get(r["n"])
    if dv:
        for k, v in dv.items():
            key_map = {"Pravna podlaga": "convention", "Definicija": "definition", "Omejitve": "omejitve",
                       "Pomembnost": "pomembnost", "Izzivi v implementaciji": "izzivi", "Primeri iz prakse": "primeri"}
            if k in key_map and not r.get(key_map[k]):
                r[key_map[k]] = v

OUT.write_text(json.dumps(results, ensure_ascii=False, indent=1), encoding="utf-8")
print(f"\nWrote {OUT} ({len(results)} folders)")
